-- public.views_leaderboard
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.views_leaderboard(p_community uuid DEFAULT NULL::uuid)
 RETURNS TABLE(creator_id uuid, name text, photo_url text, views numeric, posts integer, wins integer, markets text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with people as (
    select p.id, p.name, p.photo_url
    from public.profiles p
    where p.status = 'active'
      and p.is_test = false
      and p.is_admin = false
      and coalesce(p.is_sandbox, false) = false
      and p.deletion_requested_at is null
      and (
        public.vip_lock_community(p_community) is null
        or exists (
          select 1 from public.community_members m
          where m.profile_id = p.id and m.community_id = public.vip_lock_community(p_community) and m.status = 'active'
        )
      )
  )
  select
    pe.id,
    pe.name,
    pe.photo_url,
    coalesce(s.views, 0)::numeric,
    coalesce(s.posts, 0)::int,
    coalesce(w.wins, 0)::int,
    coalesce(mk.names, '{}')::text[]
  from people pe
  left join lateral (
    select sum(coalesce(sub.logged_views, 0)) as views, count(*)::int as posts
    from public.submissions sub where sub.creator_id = pe.id
  ) s on true
  left join lateral (
    select count(*)::int as wins
    from public.results r where r.creator_id = pe.id and r.rank = 1
  ) w on true
  left join lateral (
    select array_agg(c.name order by c.name) as names
    from public.community_members m
    join public.communities c on c.id = m.community_id
    where m.profile_id = pe.id and m.status = 'active' and c.kind = 'chapter'
  ) mk on true
  -- Everybody is on the board, including the creators sitting on zero. A
  -- leaderboard that only lists the people already winning tells a new creator
  -- nothing about where they stand.
  order by coalesce(s.views, 0) desc, coalesce(s.posts, 0) desc, pe.name;
$function$;
